<?php
require __DIR__.'/bootstrap.php';
$slug=trim($_GET['slug']??'');
if($slug===''){http_response_code(404);exit('Igreja não encontrada.');}
$q=$pdo->prepare('SELECT id,name,logo_url FROM churches WHERE slug=? AND active=1 LIMIT 1');$q->execute([$slug]);$church=$q->fetch();
if(!$church){http_response_code(404);exit('Igreja não encontrada.');}
$congId=trim($_GET['congregacao']??'');$cong=null;
if($congId!==''){$q=$pdo->prepare('SELECT id,name FROM congregations WHERE id=? AND church_id=? AND active=1');$q->execute([$congId,$church['id']]);$cong=$q->fetch();if(!$cong)$congId='';}
$ok=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  csrf_check();
  $name=trim($_POST['name']??'');$phone=preg_replace('/\D+/','',$_POST['phone']??'');
  if($name===''||strlen($phone)<10) throw new RuntimeException('Informe nome e telefone válidos.');
  if(!str_starts_with($phone,'55'))$phone='55'.$phone;
  $dupe=$pdo->prepare('SELECT 1 FROM members WHERE church_id=? AND phone=? LIMIT 1');$dupe->execute([$church['id'],$phone]);
  if($dupe->fetchColumn()) throw new RuntimeException('Este número de telefone já possui cadastro.');
  $photoUrl=null;
  if(!empty($_FILES['photo']['tmp_name'])&&is_uploaded_file($_FILES['photo']['tmp_name'])){
   if(($_FILES['photo']['size']??0)>5*1024*1024) throw new RuntimeException('A foto deve ter no máximo 5MB.');
   $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['photo']['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;
   if(!$ext) throw new RuntimeException('Formato de foto não permitido.');
   $dir=__DIR__.'/storage/member-photos/'.$church['id'];if(!is_dir($dir))mkdir($dir,0755,true);
   $file=app_uuid().'.'.$ext;move_uploaded_file($_FILES['photo']['tmp_name'],$dir.'/'.$file);$photoUrl='storage/member-photos/'.$church['id'].'/'.$file;
  }
  $id=app_uuid();
  $sql='INSERT INTO members(id,church_id,congregation_id,name,phone,email,birth_date,cpf,rg,cep,address_street,address_number,address_neighborhood,address_city,address_state,father_name,mother_name,spouse_name,marital_status,nationality,naturalness,role,department,photo_url,is_baptized,baptism_date,baptism_church,baptism_pastor,registration_status,registration_step,active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)';
  $st=$pdo->prepare($sql);$st->execute([$id,$church['id'],$congId?:null,$name,$phone,null_if_blank($_POST['email']??null),null_if_blank($_POST['birth_date']??null),null_if_blank($_POST['cpf']??null),null_if_blank($_POST['rg']??null),null_if_blank($_POST['cep']??null),null_if_blank($_POST['address_street']??null),null_if_blank($_POST['address_number']??null),null_if_blank($_POST['address_neighborhood']??null),null_if_blank($_POST['address_city']??null),null_if_blank($_POST['address_state']??null),null_if_blank($_POST['father_name']??null),null_if_blank($_POST['mother_name']??null),null_if_blank($_POST['spouse_name']??null),null_if_blank($_POST['marital_status']??null),null_if_blank($_POST['nationality']??null),null_if_blank($_POST['naturalness']??null),null_if_blank($_POST['role']??null),null_if_blank($_POST['department']??null),$photoUrl,($_POST['is_baptized']??'')==='sim'?1:0,null_if_blank($_POST['baptism_date']??null),null_if_blank($_POST['baptism_church']??null),null_if_blank($_POST['baptism_pastor']??null),'complete','complete']);
  $ok=true;
 }catch(Throwable $e){$error=$e->getMessage();}
}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Cadastro · <?=e($church['name'])?></title><link rel="stylesheet" href="assets/app.css?v=1"><style>.public-wrap{max-width:720px;margin:0 auto;padding:28px 16px}.public-head{text-align:center;margin-bottom:22px}.public-logo{width:80px;height:80px;border-radius:20px;object-fit:cover}.steps{display:flex;gap:8px;margin:18px 0}.step-pill{flex:1;padding:8px;border-radius:999px;background:#e8edf5;text-align:center;font-size:12px}.step-pill.active{background:#1f6feb;color:white}.reg-step{display:none}.reg-step.active{display:block}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:640px){.grid2{grid-template-columns:1fr}}</style></head><body><div class="public-wrap"><div class="public-head"><?php if($church['logo_url']):?><img class="public-logo" src="<?=e($church['logo_url'])?>"><?php endif?><h1><?=e($church['name'])?></h1><?php if($cong):?><p>Congregação <strong><?=e($cong['name'])?></strong></p><?php endif?><p>Preencha seus dados para se cadastrar como membro.</p></div>
<?php if($ok):?><div class="card"><h2>Cadastro realizado! 🎉</h2><p>Seu cadastro foi concluído com sucesso. Deus abençoe! 🙏</p></div><?php else:?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><div class="steps"><div class="step-pill active">1. Pessoal</div><div class="step-pill">2. Endereço</div><div class="step-pill">3. Igreja</div></div><form method="post" enctype="multipart/form-data" id="regForm"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="card reg-step active"><div class="grid2"><label>Nome completo<input name="name" required></label><label>Telefone<input name="phone" required inputmode="tel"></label><label>E-mail<input name="email" type="email"></label><label>Nascimento<input name="birth_date" type="date"></label><label>CPF<input name="cpf"></label><label>RG<input name="rg"></label><label>Estado civil<select name="marital_status"><option value="">Selecione</option><option>Solteiro(a)</option><option>Casado(a)</option><option>Divorciado(a)</option><option>Viúvo(a)</option></select></label><label>Cônjuge<input name="spouse_name"></label><label>Nome do pai<input name="father_name"></label><label>Nome da mãe<input name="mother_name"></label><label>Nacionalidade<input name="nationality" value="Brasileiro(a)"></label><label>Naturalidade<input name="naturalness"></label><label>Foto<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" capture="user"></label></div><button type="button" class="btn primary next">Continuar</button></div><div class="card reg-step"><div class="grid2"><label>CEP<input name="cep" id="cep"></label><label>Rua<input name="address_street" id="street"></label><label>Número<input name="address_number"></label><label>Bairro<input name="address_neighborhood" id="neighborhood"></label><label>Cidade<input name="address_city" id="city"></label><label>UF<input name="address_state" id="state"></label></div><div class="actions"><button type="button" class="btn prev">Voltar</button><button type="button" class="btn primary next">Continuar</button></div></div><div class="card reg-step"><div class="grid2"><label>É batizado?<select name="is_baptized"><option value="nao">Não</option><option value="sim">Sim</option></select></label><label>Data do batismo<input name="baptism_date" type="date"></label><label>Igreja do batismo<input name="baptism_church"></label><label>Pastor do batismo<input name="baptism_pastor"></label><label>Cargo/Função<input name="role"></label><label>Departamento<input name="department"></label></div><div class="actions"><button type="button" class="btn prev">Voltar</button><button class="btn primary">Concluir cadastro</button></div></div></form><?php endif?></div><script>const steps=[...document.querySelectorAll('.reg-step')],pills=[...document.querySelectorAll('.step-pill')];let i=0;function show(n){i=n;steps.forEach((x,j)=>x.classList.toggle('active',j===n));pills.forEach((x,j)=>x.classList.toggle('active',j===n))}document.querySelectorAll('.next').forEach(b=>b.onclick=()=>show(Math.min(i+1,2)));document.querySelectorAll('.prev').forEach(b=>b.onclick=()=>show(Math.max(i-1,0)));document.getElementById('cep')?.addEventListener('blur',async e=>{const c=e.target.value.replace(/\D/g,'');if(c.length!==8)return;try{const d=await(await fetch('https://viacep.com.br/ws/'+c+'/json/')).json();if(!d.erro){street.value=d.logradouro||'';neighborhood.value=d.bairro||'';city.value=d.localidade||'';state.value=d.uf||''}}catch(_){}});</script></body></html>